func TestTwoNeighboursShareWhatTheyHaveBoth(emonT *testing.T) {
	port.AssertEq(emonT, inline.IlMix(3, 1), 1, "bold italic and bold share bold")
	port.AssertEq(emonT, inline.IlMix(1, 2), 0, "bold and italic share nothing")
	port.AssertEq(emonT, inline.IlMix(1+768, 3+768), 1+768, "the same link is shared, with the bits both have")
	port.AssertEq(emonT, inline.IlMix(1+768, 1+512), 1, "two links are not")
	port.AssertEq(emonT, inline.IlMix(0, 1), 0, "plain and bold")
}

func TestAStateIsWrittenAgainstTheStyleOfTheParagraph(emonT *testing.T) {
	port.AssertEq(emonT, inline.IlEff(3, 1), 2, "bold italic in a paragraph set bold is italic")
	port.AssertEq(emonT, inline.IlEff(1, 1), 0, "bold in a paragraph set bold is not marked")
	port.AssertEq(emonT, inline.IlEff(1, 0), 1, "bold in an ordinary one is")
	port.AssertEq(emonT, inline.IlEff(33, 1), 32, "a superscript is never the paragraph's style")
	port.AssertEq(emonT, inline.IlEff(1+256, 1), 256, "the link stays")
	port.AssertEq(emonT, inline.IlEff(64, 64), 0, "a monospaced paragraph")
	port.AssertEq(emonT, inline.IlEff(128, 128), 0, "small capitals too")
	port.AssertEq(emonT, inline.IlBits(3+1024), 3, "the bits of a state")
	port.AssertEq(emonT, inline.IlLink(3+1024), 4, "its link number plus one")
}

