func TestMarkersAreReadBack(emonT *testing.T) {
	var raw *port.Cells = port.NewCells()
	itRawMark(raw, 0, port.TextBlob("ab"))
	itRawMark(raw, 7, port.TextBlob("cd"))
	itRawMark(raw, 12345, port.TextBlob("e"))
	port.AssertEq(emonT, port.CellsAt(raw, 0), inline.IlSSty(), "the opener")
	port.AssertEq(emonT, inline.IlMarkEnd(raw, 0, port.CellsLen(raw)), 3, "a marker of state 0 ends after its digit and its end")
	port.AssertEq(emonT, inline.IlMarkValue(raw, 0, 3), 0, "its state")
	port.AssertEq(emonT, inline.IlStateAt(raw, 0), 0, "before any marker")
	port.AssertEq(emonT, inline.IlStateAt(raw, 5), 0, "in the first")
	port.AssertEq(emonT, inline.IlStateAt(raw, 9), 7, "in the second: the state of the marker before it")
	port.AssertEq(emonT, inline.IlStateAt(raw, port.CellsLen(raw)), 12345, "in the last")
	port.AssertEq(emonT, inline.IlHas(raw, port.CellsLen(raw)), 1, "there are markers")
	port.AssertEq(emonT, inline.IlHas(raw, 0), 0, "and none in nothing")
	port.AssertEq(emonT, inline.IlMarkEnd(raw, 1, 2), -1, "an end past the limit is none")
}

func TestTheBaseStyleOfAParagraphIsWhatMostOfItHas(emonT *testing.T) {
	var raw *port.Cells = port.NewCells()
	itRawMark(raw, 1, port.TextBlob("bold"))
	itRawMark(raw, 0, port.TextBlob(" plain words"))
	port.AssertEq(emonT, inline.IlBaseOf(raw, port.CellsLen(raw)), 0, "four of twelve letters are bold: not the base")
	port.CellsDrop(raw, 0)
	itRawMark(raw, 1, port.TextBlob("bold bold"))
	itRawMark(raw, 0, port.TextBlob(" x"))
	port.AssertEq(emonT, inline.IlBaseOf(raw, port.CellsLen(raw)), 1, "eight of nine: bold is the paragraph's own")
	port.AssertEq(emonT, inline.IlStyled(raw, port.CellsLen(raw), 1), 0, "and what is written of it is nothing")
	port.AssertEq(emonT, inline.IlStyled(raw, port.CellsLen(raw), 0), 1, "when it is not")
	port.CellsDrop(raw, 0)
	itRawMark(raw, 3, port.TextBlob("abcd"))
	port.AssertEq(emonT, inline.IlBaseOf(raw, port.CellsLen(raw)), 3, "bold italic wholly: both")
	port.CellsDrop(raw, 0)
	port.CellsPush(raw, lists.LsSItem())
	port.CellsPush(raw, 66)
	port.CellsPush(raw, lists.LsSEnd())
	port.CellsPush(raw, 32)
	itRawMark(raw, 2, port.TextBlob("ab"))
	port.AssertEq(emonT, inline.IlBaseOf(raw, port.CellsLen(raw)), 2, "a group of another stage is not a character: all that is left is italic")
}

