func itLine(wd *port.Cells, ln *port.Cells, et *port.Cells, b []byte, y int32) int32 {
	// A line on page 1 at y (1200 tall, baseline 2 pt above its bottom): the words of the ASCII text b, 2800 apart
	// from x 7200, 11 pt, font 0, no glyphs. Answers the line's first word.
	var w0 int32 = evidence.WdCount(wd)
	var n int32 = port.BlobLen(b)
	var x int32 = 7200
	var s int32 = 0
	var k int32 = 0
	for k <= n {
		if (k == n) || (port.BlobU8(b, k) == 32) {
			if k > s {
				var ts int32 = port.CellsLen(et)
				model.TextAppendUtf8(et, b, s, k)
				var r int32 = evidence.WdNew(wd, 1, x, y, x+2400, y+1200, x, (y+1200)-200, x+2400, (y+1200)-200, 0, 0, ts, port.CellsLen(et)-ts, -1, -1, -1)
				evidence.WdSet(wd, r, evidence.WfSize(), 1100)
				evidence.WdSet(wd, r, evidence.WfFont(), 0)
				x += 2800
			}
			s = k + 1
		}
		k += 1
	}
	evidence.LnNew(ln, 1, 7200, y, x, y+1200, 7200, (y+1200)-200, x, (y+1200)-200, 0, 0, w0, evidence.WdCount(wd)-w0)
	return w0
}

