func itFind(nodes *port.Cells, kind int32, nth int32) int32 {
	// The nth node (from 0) of the kind, -1 when there are not so many.
	var n int32 = model.NodeCount(nodes)
	var i int32 = 0
	var seen int32 = 0
	for i < n {
		if model.NodeKind(nodes, i) == kind {
			if seen == nth {
				return i
			}
			seen += 1
		}
		i += 1
	}
	return -1
}

func itSays(text *port.Cells, start int32, n int32, b []byte) int32 {
	// 1 when the run text[start, start+n) is the ASCII text b.
	var i int32 = 0
	if n != port.BlobLen(b) {
		return 0
	}
	for i < port.BlobLen(b) {
		if port.CellsAt(text, start+i) != port.BlobU8(b, i) {
			return 0
		}
		i += 1
	}
	return 1
}

func itOwn(nodes *port.Cells, text *port.Cells, n int32, b []byte) int32 {
	// 1 when node n's own text is the ASCII text b.
	return itSays(text, model.NodeTextStart(nodes, n), model.NodeTextLen(nodes, n), b)
}

