func TestWordsOfOtherFontsAreSpans(emonT *testing.T) {
	var wd *port.Cells = port.NewCells()
	var ln *port.Cells = port.NewCells()
	var et *port.Cells = port.NewCells()
	var gl *port.Cells = port.NewCells()
	var ift *port.Cells = port.NewCells()
	var an *port.Cells = port.NewCells()
	var txt *port.Cells = port.NewCells()
	var nodes *port.Cells = port.NewCells()
	var attrs *port.Cells = port.NewCells()
	var regions *port.Cells = port.NewCells()
	var text *port.Cells = port.NewCells()
	var pages *port.Cells = port.NewCells()
	var ledger *port.Cells = port.NewCells()
	var layout *port.Cells = port.NewCells()
	var st *port.Cells = port.NewCells()
	itBody(wd, ln, et, port.TextBlob("alpha beta gamma delta epsilon"))
	itFonts(ift)
	// the second line is words 6..10: beta (7) is bold, gamma (8) and delta (9) are italic, epsilon (10) bold
	evidence.WdSet(wd, 7, evidence.WfFont(), 1)
	evidence.WdSet(wd, 8, evidence.WfFont(), 2)
	evidence.WdSet(wd, 9, evidence.WfFont(), 2)
	evidence.WdSet(wd, 10, evidence.WfFont(), 1)
	itBuild(wd, ln, et, gl, ift, an, txt, nodes, attrs, regions, text, pages, ledger, layout)
	var p int32 = itFind(nodes, model.NkParagraph(), 0)
	var s0 int32 = itFind(nodes, model.NkSpan(), 0)
	var s1 int32 = itFind(nodes, model.NkSpan(), 1)
	var s2 int32 = itFind(nodes, model.NkSpan(), 2)
	var c0 int32 = model.NodeFirstChild(nodes, s0)
	var c1 int32 = model.NodeFirstChild(nodes, s1)
	var c2 int32 = model.NodeFirstChild(nodes, s2)
	var pf int32 = model.NodeFirstChild(nodes, p)
	var n0 int32 = model.NodeNext(nodes, s0)
	var n2 int32 = model.NodeNext(nodes, s2)
	port.AssertEq(emonT, itFind(nodes, model.NkParagraph(), 1), -1, "one paragraph")
	port.AssertEq(emonT, itFind(nodes, model.NkSpan(), 3), -1, "and three spans in it: bold, italic (two words, one span), bold")
	port.AssertEq(emonT, model.NodeParent(nodes, s0), p, "the first is a child of the paragraph")
	port.AssertEq(emonT, model.NodeSub(nodes, s0), 1, "bold")
	port.AssertEq(emonT, model.NodeSub(nodes, s1), 2, "italic")
	port.AssertEq(emonT, model.NodeSub(nodes, s2), 1, "bold")
	port.AssertEq(emonT, itOwn(nodes, text, c0, port.TextBlob("beta")), 1, "beta")
	port.AssertEq(emonT, itOwn(nodes, text, c1, port.TextBlob("gamma delta")), 1, "gamma delta: the space between them is inside the span")
	port.AssertEq(emonT, itOwn(nodes, text, c2, port.TextBlob("epsilon")), 1, "epsilon")
	port.AssertEq(emonT, itOwn(nodes, text, pf, port.TextBlob("lorem ipsum dolor sit amet consectetur alpha ")), 1, "the first text is the line before and `alpha`, and the space before the span is outside it")
	port.AssertEq(emonT, itOwn(nodes, text, n0, port.TextBlob(" ")), 1, "the space between bold and italic is plain")
	port.AssertEq(emonT, itOwn(nodes, text, n2, port.TextBlob(" lorem ipsum dolor sit amet consectetur")), 1, "and the text after the last span goes on")
	port.AssertEq(emonT, model.ModelCheck(nodes, attrs, regions, text, pages, ledger, layout, st), 0, "a Model in document order")
}

