func TestARaisedSmallGlyphIsASuperscriptAndALoweredOneASubscript(emonT *testing.T) {
	var wd *port.Cells = port.NewCells()
	var ln *port.Cells = port.NewCells()
	var et *port.Cells = port.NewCells()
	var gl *port.Cells = port.NewCells()
	var ift *port.Cells = port.NewCells()
	var an *port.Cells = port.NewCells()
	var txt *port.Cells = port.NewCells()
	var nodes *port.Cells = port.NewCells()
	var attrs *port.Cells = port.NewCells()
	var regions *port.Cells = port.NewCells()
	var text *port.Cells = port.NewCells()
	var pages *port.Cells = port.NewCells()
	var ledger *port.Cells = port.NewCells()
	var layout *port.Cells = port.NewCells()
	var st *port.Cells = port.NewCells()
	itBody(wd, ln, et, port.TextBlob("x2 beta H2O"))
	itFonts(ift)
	// word 6 is `x2`, word 8 `H2O`: the baseline of the line is y 7400, its text 11 pt
	evidence.WdSet(wd, 6, evidence.WfGfirst(), 0)
	evidence.WdSet(wd, 6, evidence.WfGcount(), 2)
	itGlyph(gl, 7200, 8000, 120, 6, 1100, 7400)
	itGlyph(gl, 8000, 8400, 50, 6, 700, 6900)
	evidence.WdSet(wd, 8, evidence.WfGfirst(), 2)
	evidence.WdSet(wd, 8, evidence.WfGcount(), 3)
	itGlyph(gl, 12800, 13600, 72, 8, 1100, 7400)
	itGlyph(gl, 13600, 14000, 50, 8, 700, 7900)
	itGlyph(gl, 14000, 14800, 79, 8, 1100, 7400)
	itBuild(wd, ln, et, gl, ift, an, txt, nodes, attrs, regions, text, pages, ledger, layout)
	var sp int32 = itFind(nodes, model.NkSpan(), 0)
	var sb int32 = itFind(nodes, model.NkSpan(), 1)
	var cp int32 = model.NodeFirstChild(nodes, sp)
	var cb int32 = model.NodeFirstChild(nodes, sb)
	var nb int32 = model.NodeNext(nodes, sb)
	port.AssertEq(emonT, model.NodeSub(nodes, sp), 32, "the 2 of x2 is raised and small: a superscript")
	port.AssertEq(emonT, itOwn(nodes, text, cp, port.TextBlob("2")), 1, "and the span holds only it")
	port.AssertEq(emonT, model.NodeSub(nodes, sb), 16, "the 2 of H2O is lowered: a subscript")
	port.AssertEq(emonT, itOwn(nodes, text, cb, port.TextBlob("2")), 1, "only it")
	port.AssertEq(emonT, itFind(nodes, model.NkSpan(), 2), -1, "nothing else is marked")
	port.AssertEq(emonT, itOwn(nodes, text, nb, port.TextBlob("O lorem ipsum dolor sit amet consectetur")), 1, "the text after goes on")
	port.AssertEq(emonT, model.ModelCheck(nodes, attrs, regions, text, pages, ledger, layout, st), 0, "in document order")
}

func itLinkRow(an *port.Cells, x0 int32, y0 int32, x1 int32, y1 int32, act int32, ts int32, tl int32) int32 {
	// A link annotation row on page 0 (38 cells): its rectangle, the action (1 URI) and its target's run in `txt`.
	var at int32 = port.CellsLen(an)
	var i int32 = 0
	for i < 38 {
		port.CellsPush(an, 0)
		i += 1
	}
	port.CellsSet(an, at+1, 1)
	port.CellsSet(an, at+4, x0)
	port.CellsSet(an, at+5, y0)
	port.CellsSet(an, at+6, x1)
	port.CellsSet(an, at+7, y1)
	port.CellsSet(an, at+12, act)
	port.CellsSet(an, at+13, ts)
	port.CellsSet(an, at+14, tl)
	port.CellsSet(an, at+15, -1)
	return at
}

func itTxt(txt *port.Cells, b []byte) int32 {
	var i int32 = 0
	for i < port.BlobLen(b) {
		port.CellsPush(txt, port.BlobU8(b, i))
		i += 1
	}
	return 0
}

func TestAWordUnderALinkAnnotationIsALink(emonT *testing.T) {
	var wd *port.Cells = port.NewCells()
	var ln *port.Cells = port.NewCells()
	var et *port.Cells = port.NewCells()
	var gl *port.Cells = port.NewCells()
	var ift *port.Cells = port.NewCells()
	var an *port.Cells = port.NewCells()
	var txt *port.Cells = port.NewCells()
	var nodes *port.Cells = port.NewCells()
	var attrs *port.Cells = port.NewCells()
	var regions *port.Cells = port.NewCells()
	var text *port.Cells = port.NewCells()
	var pages *port.Cells = port.NewCells()
	var ledger *port.Cells = port.NewCells()
	var layout *port.Cells = port.NewCells()
	var st *port.Cells = port.NewCells()
	itBody(wd, ln, et, port.TextBlob("alpha beta gamma delta"))
	itFonts(ift)
	itTxt(txt, port.TextBlob("https://example.org/x"))
	// beta is at x 10000..12400 and gamma at 12800..15200, on y 6400..7600: the link covers beta and gamma
	itLinkRow(an, 10000, 6400, 15200, 7600, 1, 0, 21)
	// a link to javascript, over delta, is no link
	itTxt(txt, port.TextBlob("javascript:x"))
	itLinkRow(an, 15600, 6400, 18000, 7600, 1, 21, 12)
	port.AssertEq(emonT, itBuild(wd, ln, et, gl, ift, an, txt, nodes, attrs, regions, text, pages, ledger, layout), 1, "one link found")
	var p int32 = itFind(nodes, model.NkParagraph(), 0)
	var lk int32 = itFind(nodes, model.NkLink(), 0)
	var a int32 = model.NodeAttr(nodes, attrs, lk, model.FkHref())
	var lc int32 = model.NodeFirstChild(nodes, lk)
	var pf int32 = model.NodeFirstChild(nodes, p)
	var ln1 int32 = model.NodeNext(nodes, lk)
	port.AssertEq(emonT, itFind(nodes, model.NkLink(), 1), -1, "and only one")
	port.AssertEq(emonT, model.NodeParent(nodes, lk), p, "in the paragraph")
	port.AssertEq(emonT, itSays(text, model.AttrValue(attrs, a), model.AttrLen(attrs, a), port.TextBlob("https://example.org/x")), 1, "its href")
	port.AssertEq(emonT, itOwn(nodes, text, lc, port.TextBlob("beta gamma")), 1, "holds the two words and the space between them")
	port.AssertEq(emonT, itOwn(nodes, text, pf, port.TextBlob("lorem ipsum dolor sit amet consectetur alpha ")), 1, "the text before it")
	port.AssertEq(emonT, itOwn(nodes, text, ln1, port.TextBlob(" delta lorem ipsum dolor sit amet consectetur")), 1, "and after it, delta is not linked")
	port.AssertEq(emonT, model.ModelCheck(nodes, attrs, regions, text, pages, ledger, layout, st), 0, "in document order")
}

func itBlock(nodes *port.Cells, regions *port.Cells, kind int32, parent int32, y0 int32, y1 int32) int32 {
	// A block of the kind on page 1 whose region is x 7200..50000 and y0..y1; answers its node.
	var n int32 = model.NodeNew(nodes, kind, parent)
	model.NodeAddRegion(nodes, regions, n, 1, 7200, y0, 50000, y1)
	return n
}

func itLink(nodes *port.Cells, attrs *port.Cells, text *port.Cells, parent int32, page int32, ypt int32, inner []byte) int32 {
	// A link to page `page` whose point is ypt points down, holding a span holding a text: answers the link.
	var lk int32 = model.NodeNew(nodes, model.NkLink(), parent)
	var sp int32 = model.NodeNew(nodes, model.NkSpan(), lk)
	var tx int32 = model.NodeNew(nodes, model.NkText(), sp)
	var t0 int32 = port.CellsLen(text)
	model.NodeSetSub(nodes, lk, page)
	model.NodeSetAux(nodes, lk, (ypt+1)*32768)
	model.NodeSetSub(nodes, sp, 1)
	model.TextAppendUtf8(text, inner, 0, port.BlobLen(inner))
	model.NodeSetText(nodes, tx, t0, port.CellsLen(text)-t0)
	return lk
}

func itRs(on *port.Cells, oa *port.Cells, orr *port.Cells, text *port.Cells, nodes *port.Cells, attrs *port.Cells, regions *port.Cells) int32 {
	var nm *port.Cells = port.NewCells()
	var stk *port.Cells = port.NewCells()
	var used *port.Cells = port.NewCells()
	var out *port.Cells = port.NewCells()
	var lay *port.Cells = port.NewCells()
	return restruct.RsRun(on, oa, orr, text, nodes, attrs, regions, nm, stk, used, out, lay)
}

func TestAnInternalLinkFindsTheBlockItNames(emonT *testing.T) {
	var on *port.Cells = port.NewCells()
	var oa *port.Cells = port.NewCells()
	var orr *port.Cells = port.NewCells()
	var text *port.Cells = port.NewCells()
	var nodes *port.Cells = port.NewCells()
	var attrs *port.Cells = port.NewCells()
	var regions *port.Cells = port.NewCells()
	var pages *port.Cells = port.NewCells()
	var ledger *port.Cells = port.NewCells()
	var layout *port.Cells = port.NewCells()
	var st *port.Cells = port.NewCells()
	model.ModelInit(on, oa, orr, text, pages, ledger, layout)
	model.PageNew(pages, 1, 61200, 79200, 0, model.PkVector())
	// a heading at y 20..30 pt, a paragraph (4 links in it) at 40..50, another at 80..90, a third on page 2
	itBlock(on, orr, model.NkHeading(), 0, 2000, 3000)
	var p1 int32 = itBlock(on, orr, model.NkParagraph(), 0, 4000, 5000)
	itLink(on, oa, text, p1, 1, 18, port.TextBlob("see http://x.org/a"))
	itLink(on, oa, text, p1, 1, 60, port.TextBlob("below"))
	itLink(on, oa, text, p1, 1, 41, port.TextBlob("inside"))
	itLink(on, oa, text, p1, 2, 5, port.TextBlob("later"))
	itBlock(on, orr, model.NkParagraph(), 0, 8000, 9000)
	var p3 int32 = model.NodeNew(on, model.NkParagraph(), 0)
	model.NodeAddRegion(on, orr, p3, 2, 7200, 1000, 50000, 2000)
	// the nodes: 0 document, 1 heading, 2 paragraph, then each link is three (link, span, text): 3, 6, 9, 12; 15, 16
	port.AssertEq(emonT, itRs(on, oa, orr, text, nodes, attrs, regions), 17, "the same Model, restructured")
	port.AssertEq(emonT, model.NodeAttrIntOr(nodes, attrs, 3, model.FkTarget(), -1), 1, "a point a little above the heading is the heading")
	port.AssertEq(emonT, model.NodeSub(nodes, 3), 0, "and the destination is taken out")
	port.AssertEq(emonT, model.NodeAttrIntOr(nodes, attrs, 6, model.FkTarget(), -1), 15, "a point below the first paragraph names the next block")
	port.AssertEq(emonT, model.NodeAttrIntOr(nodes, attrs, 9, model.FkTarget(), -1), 2, "a point inside a paragraph names it")
	port.AssertEq(emonT, model.NodeAttrIntOr(nodes, attrs, 12, model.FkTarget(), -1), 16, "a point on page 2 names the block there")
	port.AssertEq(emonT, itFind(nodes, model.NkLink(), 4), -1, "and the bare URL under the first link is not made a link again")
	port.AssertEq(emonT, model.ModelCheck(nodes, attrs, regions, text, pages, ledger, layout, st), 0, "in document order")
}

func TestRtlLinksFollowTheLogicalCharacterNotThePaintedIndex(emonT *testing.T) {
	var wd *port.Cells = port.NewCells()
	var ln *port.Cells = port.NewCells()
	var et *port.Cells = port.NewCells()
	var gl *port.Cells = port.NewCells()
	var ift *port.Cells = port.NewCells()
	var an *port.Cells = port.NewCells()
	var txt *port.Cells = port.NewCells()
	var nodes *port.Cells = port.NewCells()
	var attrs *port.Cells = port.NewCells()
	var regions *port.Cells = port.NewCells()
	var text *port.Cells = port.NewCells()
	var pages *port.Cells = port.NewCells()
	var ledger *port.Cells = port.NewCells()
	var layout *port.Cells = port.NewCells()
	itBody(wd, ln, et, port.TextBlob("אב"))
	itFonts(ift)
	itGlyph(gl, 7200, 8400, 1489, 6, 1100, 7400)
	itGlyph(gl, 8400, 9600, 1488, 6, 1100, 7400)
	evidence.WdSet(wd, 6, evidence.WfGfirst(), 0)
	evidence.WdSet(wd, 6, evidence.WfGcount(), 2)
	evidence.WdSet(wd, 6, evidence.HdDir(), 1)
	itTxt(txt, port.TextBlob("https://example.org/x"))
	itLinkRow(an, 8401, 6400, 9600, 7600, 1, 0, 21)
	port.AssertEq(emonT, itBuild(wd, ln, et, gl, ift, an, txt, nodes, attrs, regions, text, pages, ledger, layout), 1, "one link")
	var link int32 = itFind(nodes, model.NkLink(), 0)
	var child int32 = model.NodeFirstChild(nodes, link)
	port.AssertEq(emonT, model.NodeTextLen(nodes, child), 1, "one linked character")
	port.AssertEq(emonT, port.CellsAt(text, model.NodeTextStart(nodes, child)), 1488, "alef at the right is the linked logical first character")
}
